                )
            }
            if (optimizeAction != null) {
                addView(
                    TextView(this@MainActivity).apply {
                        text = if (isFarsiSub) "⚡ بهینه‌سازی خط من" else "⚡ Optimize"
                        textSize = 11.5f
                        typeface = CatClientBodyBoldTypeface
                        setTextColor(TEAL)
