                                if (existing != null) {
                                    userSubscriptionManager.update(existing.id, subTitle, raw)
                                } else {
                                    userSubscriptionManager.add(subTitle, raw)
                                }
                            }
                            userSubscriptionManager.select(saved.id)
                            val curAether = aetherPreferenceStore.read()
