     * Combines parallel Non-Cloudflare & Iran Domestic Whitelist scanning (22 targets),
     * Anti-DPI Serverless-v52 fragmented TLS verification, Deep `/24` Neighbor Harvesting around
     * live whitelist hits, 16KB Upload-Freeze Speed Testing, and 1-tap Subscription Injection.
     */
    private fun showWhitelistSuperScannerDialog() {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val rootScroll = ScrollView(this).apply {
            isFillViewport = true
        }
        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutDirection = View.LAYOUT_DIRECTION_LOCALE
            setPadding(dp(18), dp(14), dp(18), dp(18))
        }
        rootScroll.addView(container)

        container.addView(
            TextView(this).apply {
                text = if (isFarsi) {
                    "🏳️ ابر-اسکنر آی‌پی‌های سفید، پلتفرم‌ها و نت ملی (نسخه ۲۰۲۶)\n" +
                        "• اسکن موازی ۲۲ هدف سفید (آروان، دراک، پارس‌پک، ستون، فستلی، گیت‌هاب، آکامای، گوگل، آژور، Vercel، Render، Fly.io)\n" +
                        "• مجهز به برش دو مرحله‌ای Serverless-v52 در هندشیک TLS برای کشف آی‌پی‌هایی که اسکنرهای عادی نمی‌بینند\n" +
                        "• استخراج خودکار همسایه‌های زیرشبکه /24 اطراف هر آی‌پی سفید باز و تزریق ۱-کلیکی به اشتراک"
                } else {
                    "🏳️ 2026 Ultimate Whitelist, Multi-CDN & Anti-DPI Super-Scanner\n" +
                        "• Parallel scan across 22 Whitelist & Non-CF CDN targets (Arvan, Derak, ParsPack, Sotoon, Fastly, GitHub, Akamai, Google, Azure, Vercel, Render, Fly.io)\n" +
                        "• Powered by Serverless-v52 two-stage TLS fragmentation\n" +
                        "• Deep /24 subnet neighbor harvesting + 1-tap config injection"
                }
                textSize = 12f
                typeface = CatClientBodyTypeface
                setTextColor(TEXT_SECONDARY)
                setLineSpacing(dp(3).toFloat(), 1f)
            },
            LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(12) },
        )

        val liveStatusView = TextView(this).apply {
            text = if (isFarsi) {
                "📊 آماده اسکن — یکی از عملیات‌های زیر را انتخاب کنید:"
            } else {
                "📊 Ready — choose a scan operation below:"
            }
            textSize = 12f
            typeface = CatClientDataTypeface
            setTextColor(TEAL)
            background = glassSurfaceDrawable(radiusDp = 14)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            setLineSpacing(dp(3).toFloat(), 1f)
            setTextIsSelectable(true)
        }
        container.addView(liveStatusView, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(12) })

        val discoveredWhitelistResults = mutableListOf<IpScanner.ScanResult>()

        fun makeSuperBtn(label: String, filled: Boolean = false, accentColor: Int = TEAL, onClick: () -> Unit): MaterialButton =
            MaterialButton(this).apply {
                text = label
                isAllCaps = false
                textSize = 12f
                typeface = CatClientBodyBoldTypeface
                cornerRadius = dp(12)
                minHeight = dp(46)
                if (filled) {
                    backgroundTintList = ColorStateList.valueOf(accentColor)
                    setTextColor(palette.onAccent)
                } else {
                    backgroundTintList = ColorStateList.valueOf(withAlpha(accentColor, 34))
                    strokeColor = ColorStateList.valueOf(accentColor)
                    strokeWidth = dp(1)
                    setTextColor(TEXT_PRIMARY)
                }
                setOnClickListener { onClick() }
            }

        // Action 1: Parallel Scan of All 22 Whitelist & Non-CF CDN Targets (with Anti-DPI Split Fallback)
        container.addView(
            makeSuperBtn(
                label = if (isFarsi) "🏳️ ۱) اسکن موازی همهٔ ۲۲ هدف آی‌پی سفید و CDNهای غیرکلادفلر (ایران + جهانی)"
                else "🏳️ 1) Parallel Scan All 22 Whitelist & Non-CF CDN Targets (Iran + Global)",
                filled = true,
            ) {
                liveStatusView.text = if (isFarsi) {
                    "⏳ در حال اسکن موازی ۲۲ درگاه سفید (آروان، دراک، پارس‌پک، ستون، فستلی، گیت‌هاب، آکامای، گوگل، آژور، Vercel، Render، Fly.io) با برش ضد-DPI…"
                } else {
                    "⏳ Scanning 22 Whitelist & Non-CF CDN targets in parallel with Anti-DPI fragmentation…"
                }
                activityScope.launch {
                    val hits = withContext(Dispatchers.IO) {
                        LocalSniSpoofProxy.scanNonCloudflareWhitelistTargets(
                            providerFilter = null,
                            timeoutMs = 1_100,
                            useAntiDpiSplit = true,
                        )
                    }
                    val mapped = hits.map { h ->
                        IpScanner.ScanResult(
                            ip = h.target.ip,
                            pingMs = h.effectiveRttMs,
                            sni = h.target.sni,
                            tlsMs = h.tlsRttMs,
                            colo = h.target.provider.id.uppercase(),
                            tlsOk = h.tlsVerified,
                            httpStatus = if (h.tlsVerified) 200 else null,
                            port = h.target.port,
                            countryCode = IpScanner.detectCountryCodeForWhitelistIp(h.target.ip),
                            countryName = IpScanner.detectEdgeLabelForIp(h.target.ip, h.target.provider.id),
                            sourceRange = "whitelist-${h.target.provider.id}",
                            verifyTls = true,
                        )
                    }
                    discoveredWhitelistResults.clear()
                    discoveredWhitelistResults.addAll(mapped)
                    if (mapped.isNotEmpty()) {
                        val merged = (mapped + scannerResults).distinctBy { it.authority }
                            .sortedWith(compareBy({ if (it.tlsOk) 0 else 1 }, { it.pingMs }))
                        scannerResults = merged
                        runCatching { renderScannerResults() }
                        runCatching {
                            scannerApplyButton.isEnabled = merged.any { it.tlsOk }
                            scannerBuildButton.isEnabled = merged.any { it.tlsOk }
                            scannerSpeedTestButton?.isEnabled = merged.any { it.tlsOk }
                        }
                    }
                    liveStatusView.text = buildString {
                        if (isFarsi) {
                            appendLine("✅ اسکن موازی وایت‌لیست کامل شد: ${hits.size} آی‌پی سفید پاسخ‌گو (${hits.count { it.tlsVerified }} تایید کامل TLS)")
                            appendLine("────────────────────────────")
                            hits.take(12).forEachIndexed { i, h ->
                                val tlsTag = if (h.tlsVerified) "TLS✓ (${h.tlsRttMs}ms)" else "TCP✓ (${h.tcpRttMs}ms)"
                                appendLine("${i + 1}. ${h.exactEndpoint} | $tlsTag | SNI: ${h.target.sni}")
                                appendLine("   👈 ${h.target.noteFa}")
                            }
                            if (hits.isNotEmpty()) {
                                appendLine("────────────────────────────")
                                append("💡 این آی‌پی‌ها به جدول اصلی اسکنر هم اضافه شدند! حالا می‌توانید دکمه ۲ (کشف همسایه‌های /24) یا دکمه ۵ (تزریق به اشتراک) را بزنید.")
                            }
                        } else {
                            appendLine("✅ Whitelist Scan Complete: ${hits.size} reachable (${hits.count { it.tlsVerified }} TLS verified)")
                            hits.take(12).forEachIndexed { i, h ->
                                val tlsTag = if (h.tlsVerified) "TLS✓ (${h.tlsRttMs}ms)" else "TCP✓ (${h.tcpRttMs}ms)"
                                appendLine("${i + 1}. ${h.exactEndpoint} | $tlsTag | SNI: ${h.target.sni}")
                            }
                        }
                    }
                }
            },
            LinearLayout.LayoutParams(-1, -2),
        )

        // Action 2: Deep /24 Whitelist Subnet Neighbor Harvester
        container.addView(
            makeSuperBtn(
                label = if (isFarsi) "👑 ۲) کشف خودکار همسایه‌های /24 اطراف آی‌پی‌های سفید باز (استخراج ده‌ها آی‌پی سفید جدید)"
                else "👑 2) Harvest /24 Subnet Neighbors Around Live Whitelist Hits",
                accentColor = AMBER,
            ) {
                val basePool = if (discoveredWhitelistResults.isNotEmpty()) discoveredWhitelistResults else scannerResults
                val topSeeds = basePool.filter { it.tlsOk }.ifEmpty { basePool }.take(3)
                if (topSeeds.isEmpty()) {
                    Toast.makeText(
                        this,
                        if (isFarsi) "⚠️ ابتدا دکمه ۱ را بزنید تا آی‌پی‌های سفید اولیه پیدا شوند."
                        else "⚠️ Run step 1 first to discover initial whitelist seeds.",
                        Toast.LENGTH_SHORT,
                    ).show()
                    return@makeSuperBtn
                }
                val seedIps = topSeeds.map { it.ip }
                val primarySni = topSeeds.first().sni.ifBlank { "ebanksepah.ir" }
                val primaryPort = topSeeds.first().port
                val expandedNeighbors = IpScanner.expandAroundGoldenHits(seedIps, radius = 16)
                liveStatusView.text = if (isFarsi) {
                    "👑 در حال اسکن موازی ${expandedNeighbors.size} آی‌پی همسایه در زیرشبکه /24 اطراف ${seedIps.joinToString(", ")} با SNI=$primarySni و برش ضد-DPI…"
                } else {
                    "👑 Scanning ${expandedNeighbors.size} neighbor IPs in /24 around ${seedIps.joinToString(", ")}…"
                }
                activityScope.launch {
                    val foundNeighbors = withContext(Dispatchers.IO) {
                        IpScanner.scan(
                            this@MainActivity,
                            IpScanner.ScanOptions(
                                sni = primarySni,
                                port = primaryPort,
                                ports = listOf(primaryPort),
                                customSubnets = expandedNeighbors.joinToString(","),
                                includeBuiltin = false,
                                includeIranLibrary = false,
                                includeIpv6 = true,
                                perRange = 1,
                                randomSample = false,
                                concurrency = 20,
                                connectTimeoutMs = 1_100,
                                tlsTimeoutMs = 1_800,
                                verifyHttp = false,
                                antiDpiFragment = true,
                                fragmentMode = "v52-fragA",
                            ),
                        )
                    }
                    val verifiedNeighbors = foundNeighbors.filter { it.tlsOk }.ifEmpty { foundNeighbors }
                    if (verifiedNeighbors.isNotEmpty()) {
                        discoveredWhitelistResults.addAll(verifiedNeighbors)
                        val merged = (verifiedNeighbors + scannerResults).distinctBy { it.authority }
                            .sortedWith(compareBy({ if (it.tlsOk) 0 else 1 }, { it.pingMs }))
                        scannerResults = merged
                        runCatching { renderScannerResults() }
                        runCatching {
                            scannerApplyButton.isEnabled = merged.any { it.tlsOk }
                            scannerBuildButton.isEnabled = merged.any { it.tlsOk }
                        }
                    }
                    liveStatusView.text = buildString {
                        if (isFarsi) {
                            appendLine("👑 نتیجهٔ کشف زیرشبکه /24 وایت‌لیست: ${verifiedNeighbors.size} آی‌پی همسایهٔ جدید از ${expandedNeighbors.size} آی‌پی پاسخ دادند!")
                            appendLine("────────────────────────────")
                            verifiedNeighbors.take(10).forEachIndexed { idx, r ->
                                appendLine("${idx + 1}. ${r.authority} · ${r.pingMs}ms · ${r.countryName ?: "Whitelist"} (SNI: ${r.sni})")
                            }
                        } else {
                            appendLine("👑 /24 Neighbor Harvest: ${verifiedNeighbors.size}/${expandedNeighbors.size} new sibling IPs responded!")
                            verifiedNeighbors.take(10).forEachIndexed { idx, r ->
                                appendLine("${idx + 1}. ${r.authority} · ${r.pingMs}ms (SNI: ${r.sni})")
                            }
                        }
                    }
                }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) },
        )

        // Action 3: Multi-Port Cloudflare Golden F&F + IPv6 Anti-DPI Scan (6 TLS ports)
        container.addView(
            makeSuperBtn(
                label = if (isFarsi) "🔥 ۳) اسکن ۶ پورت TLS روی لبه‌های طلایی کلادفلر (F&F ایرانسل + همراه اول IPv6)"
                else "🔥 3) Scan 6 TLS Ports on Golden Cloudflare F&F + MCI IPv6 Edges",
            ) {
                liveStatusView.text = if (isFarsi) {
                    "🔥 در حال اسکن ۶ پورت TLS (443, 2053, 2083, 2087, 2096, 8443) روی لبه‌های طلایی کلادفلر…"
                } else {
                    "🔥 Scanning 6 TLS ports across golden Cloudflare F&F & IPv6 edges…"
                }
                activityScope.launch {
                    val cfHits = withContext(Dispatchers.IO) {
                        WhiteDnsSmartScanner.scanCloudflareSixPortsAndSni(
                            customSni = scannerSniPreference().ifBlank { "speed.cloudflare.com" },
                            maxHosts = 6,
                            timeoutMs = 1_100,
                        )
                    }
                    val mappedCf = cfHits.map { h ->
                        IpScanner.ScanResult(
                            ip = h.host.removeSurrounding("[", "]"),
                            pingMs = h.rttMs,
                            sni = h.sni,
                            tlsMs = h.rttMs,
                            tlsOk = true,
                            port = h.port,
                            countryName = "Cloudflare Golden Edge",
                            sourceRange = "cf-golden-6port",
                            verifyTls = true,
                        )
                    }
                    if (mappedCf.isNotEmpty()) {
                        discoveredWhitelistResults.addAll(mappedCf)
                        val merged = (mappedCf + scannerResults).distinctBy { it.authority }
                            .sortedWith(compareBy({ if (it.tlsOk) 0 else 1 }, { it.pingMs }))
                        scannerResults = merged
                        runCatching { renderScannerResults() }
                    }
                    liveStatusView.text = buildString {
                        if (isFarsi) {
                            appendLine("🔥 نتیجهٔ اسکن ۶ پورت طلایی کلادفلر: ${cfHits.size} زوج IP:port باز پیدا شد!")
                            cfHits.forEachIndexed { idx, h ->
                                appendLine("${idx + 1}. ${h.endpoint} · ${h.rttMs}ms · SNI: ${h.sni}")
                            }
                        } else {
                            appendLine("🔥 Golden 6-Port Scan: ${cfHits.size} open IP:port pairs found!")
                            cfHits.forEachIndexed { idx, h ->
                                appendLine("${idx + 1}. ${h.endpoint} · ${h.rttMs}ms · SNI: ${h.sni}")
                            }
                        }
                    }
                }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) },
        )

        // Action 4: Real 16KB Upload-Freeze & Download Throughput Test on Best Discovered IPs
        container.addView(
            makeSuperBtn(
                label = if (isFarsi) "🧪 ۴) تست واقعی سرعت دانلود + تست ضد-فریز آپلود ۱۶ کیلوبایت روی بهترین آی‌پی‌ها"
                else "🧪 4) Real Download Speed + 16KB Upload-Freeze Probe on Best Hits",
            ) {
                val pool = (discoveredWhitelistResults + scannerResults).distinctBy { it.authority }
                    .filter { it.tlsOk }
                    .take(3)
                if (pool.isEmpty()) {
                    Toast.makeText(
                        this,
                        if (isFarsi) "⚠️ ابتدا دکمه ۱ یا ۳ را بزنید تا آی‌پی‌های باز پیدا شوند."
                        else "⚠️ Run step 1 or 3 first.",
                        Toast.LENGTH_SHORT,
                    ).show()
                    return@makeSuperBtn
                }
                liveStatusView.text = if (isFarsi) {
                    "🧪 در حال تست واقعی انتقال دیتا و بررسی قفل آپلود ۱۶ کیلوبایت روی ${pool.size} آی‌پی برتر…"
                } else {
                    "🧪 Probing download throughput & 16KB upload-freeze survival on top ${pool.size} endpoints…"
                }
                activityScope.launch {
                    val lines = withContext(Dispatchers.IO) {
                        pool.map { r ->
                            val rep = LocalSniSpoofProxy.probeTunnelSpeedAndUploadFreeze(
                                host = r.ip,
                                port = r.port,
                                sni = r.sni.ifBlank { "speed.cloudflare.com" },
                                timeoutMs = 2_400,
                            )
                            r to rep
                        }
                    }
                    liveStatusView.text = buildString {
                        if (isFarsi) {
                            appendLine("🧪 نتیجهٔ تست واقعی سرعت و ضد-فریز ۱۶ کیلوبایت:")
                            appendLine("────────────────────────────")
                            lines.forEachIndexed { idx, (r, rep) ->
                                val upBadge = if (rep.uploadBurstHealthy) "🟢 بدون قفل آپلود 16KB" else "🟠 حساس به آپلود (نیازمند برش v52)"
                                appendLine("${idx + 1}. ${r.authority} (${r.countryName ?: "Edge"})")
                                appendLine("   👈 پینگ: ${rep.pingMs}ms | دانلود: ${rep.downloadSpeedMbps} Mbps | آپلود: ${rep.uploadBurstSpeedMbps} Mbps | $upBadge")
                            }
                        } else {
                            appendLine("🧪 Speed & 16KB Upload-Freeze Results:")
                            lines.forEachIndexed { idx, (r, rep) ->
                                appendLine("${idx + 1}. ${r.authority} -> ${rep.pingMs}ms | Down: ${rep.downloadSpeedMbps} Mbps | 16KB Upload OK: ${rep.uploadBurstHealthy}")
                            }
                        }
                    }
                }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) },
        )

        // Action 5: 1-Tap Inject Verified Whitelist/Clean IPs into Subscriptions & Connect
        container.addView(
            makeSuperBtn(
                label = if (isFarsi) "💉 ۵) تزریق آی‌پی‌های سفید/تمیز پیدا شده به کانفیگ‌های من و اتصال فوری"
                else "💉 5) Inject Discovered Whitelist/Clean IPs into My Configs & Connect",
                filled = true,
            ) {
                val combined = (discoveredWhitelistResults + scannerResults).distinctBy { it.authority }
                if (combined.isEmpty()) {
                    Toast.makeText(
                        this,
                        if (isFarsi) "⚠️ ابتدا دکمه ۱ را بزنید تا آی‌پی‌های سفید اسکن شوند."
                        else "⚠️ Run step 1 first to scan whitelist IPs.",
                        Toast.LENGTH_SHORT,
                    ).show()
                } else {
                    injectScannedIpsIntoActiveSubscription(combined)
                }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(10) },
        )

        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "🏳️ ابر-اسکنر آی‌پی سفید، پلتفرم‌ها و نت ملی"
                else "🏳️ Whitelist, Multi-CDN & Net Melli Super-Scanner",
            )
            .setView(rootScroll)
            .setPositiveButton(android.R.string.ok, null)
            .create()
            .showCatClientDialog()
    }

    /**
     * 1-Click Hotspot / Wi-Fi Proxy Share with live QR Code (`HTTP CONNECT` + `SOCKS5` dual-protocol server):
     * Lets iPhones, Windows/Mac laptops, PlayStation/Xbox consoles, and Smart TVs on the same Wi-Fi or Hotspot
     * share the phone's VPN internet without installing any app.
     */
    private fun showEasyHotspotShareWithQrDialog() {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        activityScope.launch {
            val (port, lanIps) = withContext(Dispatchers.IO) {
                val p = LocalSniSpoofProxy.startLanHotspotShareProxy(LocalSniSpoofProxy.DEFAULT_LAN_HOTSPOT_PORT)
                val ips = LocalSniSpoofProxy.detectDeviceLanIpAddresses()
                p to ips
            }
            val primaryIp = lanIps.firstOrNull() ?: "192.168.43.1"
            val proxyAddress = "$primaryIp:$port"
            val allIpsText = lanIps.joinToString(" ، ") { "$it:$port" }
            val qrPayload = "socks5://$primaryIp:$port#CatClient-Hotspot-VPN"
            val qrBitmap = withContext(Dispatchers.Default) {
                QrCodes.bitmap(qrPayload, sizePx = dp(210))
            }

            val box = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER_HORIZONTAL
                setPadding(dp(20), dp(14), dp(20), dp(8))
            }

            if (qrBitmap != null) {
                val qrView = ImageView(this@MainActivity).apply {
                    setImageBitmap(qrBitmap)
                    scaleType = ImageView.ScaleType.FIT_CENTER
                }
                box.addView(qrView, LinearLayout.LayoutParams(dp(200), dp(200)).apply { bottomMargin = dp(10) })
            }

            val infoView = TextView(this@MainActivity).apply {
                textSize = 13f
                setTextColor(TEXT_PRIMARY)
                setLineSpacing(0f, 1.25f)
                text = if (isFarsi) {
                    buildString {
                        appendLine("🟢 پروکسی دوگانهٔ هات‌اسپات و وای‌فای فعال شد!")
                        appendLine()
                        appendLine("📌 آدرس سرور (IP):  $primaryIp")
                        appendLine("📌 پورت (Port):      $port")
                        if (lanIps.size > 1) {
                            appendLine("📌 سایر آدرس‌های شبکه شما: $allIpsText")
                        }
                        appendLine()
                        appendLine("💡 چطور روی دستگاه‌های دیگر وصل شوم؟ (بدون نصب هیچ برنامه‌ای):")
                        appendLine("• 🍎 آیفون و آیپد: وارد Settings -> Wi-Fi شوید، روی ⓘ جلوی وای‌فای بزنید، پایین صفحه Configure Proxy را روی Manual بگذارید و Server = $primaryIp و Port = $port را وارد کنید.")
                        appendLine("• 💻 ویندوز و مک: در تنظیمات Proxy سیستم، آدرس $primaryIp و پورت $port را وارد کنید.")
                        appendLine("• 🎮 پلی‌استیشن / تلویزیون / تلگرام: هم از پروکسی HTTP و هم از پروکسی SOCKS5 روی همین آدرس $proxyAddress پشتیبانی می‌کند!")
                    }
                } else {
                    buildString {
                        appendLine("🟢 Dual-Protocol (HTTP + SOCKS5) Wi-Fi/Hotspot Proxy is LIVE!")
                        appendLine()
                        appendLine("📌 Server IP:   $primaryIp")
                        appendLine("📌 Port:        $port")
                        appendLine()
                        appendLine("• iPhone / iPad: Settings -> Wi-Fi -> (i) -> Configure Proxy -> Manual -> Server: $primaryIp, Port: $port")
                        appendLine("• Windows / Mac / PS5 / Telegram: Supports both HTTP Proxy and SOCKS5 on $proxyAddress.")
                    }
                }
            }
            box.addView(infoView, LinearLayout.LayoutParams(-1, -2))

            MaterialAlertDialogBuilder(this@MainActivity)
                .setTitle(
                    if (isFarsi) "📲 اشتراک‌گذاری اینترنت VPN با بارکد QR (هات‌اسپات و وای‌فای)"
                    else "📲 Share VPN over Wi-Fi / Hotspot with QR Code",
                )
                .setView(box)
                .setNeutralButton(
                    if (isFarsi) "⏹ توقف اشتراک‌گذاری" else "⏹ Stop Proxy",
                ) { _, _ ->
                    LocalSniSpoofProxy.stopLanHotspotShareProxy()
                    Toast.makeText(
                        this@MainActivity,
                        if (isFarsi) "پروکسی اشتراک‌گذاری هات‌اسپات متوقف شد" else "Hotspot proxy stopped",
                        Toast.LENGTH_SHORT,
                    ).show()
                }
                .setNegativeButton(
                    if (isFarsi) "📋 کپی آی‌پی و پورت" else "📋 Copy IP:Port",
                ) { _, _ ->
                    val cm = getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
                    cm.setPrimaryClip(ClipData.newPlainText("Hotspot Proxy", proxyAddress))
                    Toast.makeText(
                        this@MainActivity,
                        if (isFarsi) "✅ آدرس $proxyAddress کپی شد" else "✅ Copied $proxyAddress",
                        Toast.LENGTH_SHORT,
                    ).show()
                }
                .setPositiveButton(android.R.string.ok, null)
                .create()
                .showCatClientDialog()
        }
    }

    /**
     * 1-Click Parallel Dead-Config Cleaner & Fastest-Ping Sorter:
     * Tests all configs in the user's current subscription (plus clipboard if present),
     * removes dead/timed-out servers, auto-repairs blocked Cloudflare configs via Multi-Chunk SNI Split,
     * sorts by real ping (`ms`), and saves + connects immediately.
     */
    private fun runOneClickCleanAndSortConfigsDialog(mergeIntoSuperSubscription: Boolean = false) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        Toast.makeText(
            this,
            if (isFarsi) "🧹 در حال تست موازی کانفیگ‌ها، حذف سرورهای سوخته و مرتب‌سازی بر اساس سریع‌ترین پینگ…"
            else "🧹 Probing configs in parallel, removing dead servers & sorting by fastest ping…",
            Toast.LENGTH_SHORT,
        ).show()

        activityScope.launch {
            val rawSources = mutableListOf<String>()
            val cm = getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
            val clipText = cm.primaryClip?.getItemAt(0)?.coerceToText(this@MainActivity)?.toString().orEmpty().trim()
            if (clipText.isNotBlank()) rawSources += clipText
            val selectedId = userSubscriptionManager.selectedId()
            val subs = userSubscriptionManager.list()
            val activeSub = subs.firstOrNull { it.id == selectedId } ?: subs.firstOrNull()
            for (sub in subs) {
                rawSources += sub.input
                val snap = runCatching { userSubscriptionManager.cachedSnapshot(sub.id) }.getOrNull()
                snap?.catalog?.profiles?.forEach { p ->
                    val link = p.shareLink?.trim().orEmpty()
                    if (link.isNotEmpty()) rawSources += link
                }
            }

            val report = withContext(Dispatchers.IO) {
                LocalSniSpoofProxy.cleanAndSortRawConfigLines(rawSources, timeoutMs = 1_100)
            }

            if (report.sortedAliveLinks.isEmpty()) {
                Toast.makeText(
                    this@MainActivity,
                    if (isFarsi) "⚠️ هیچ کانفیگ شخصی در اشتراک یا کلیپ‌بورد یافت نشد؛ در حال اتصال با موتور پیشنهادی…"
                    else "⚠️ No personal configs found; launching recommended connection wizard…",
                    Toast.LENGTH_LONG,
                ).show()
                showRecommendedOneClickConnectWizardDialog()
                return@launch
            }

            val summary = if (isFarsi) {
                buildString {
                    appendLine("✅ پالایش و مرتب‌سازی کانفیگ‌ها کامل شد!")
                    appendLine()
                    appendLine("• کل کانفیگ‌های بررسی‌شده: ${report.totalChecked}")
                    appendLine("• کانفیگ‌های سالم و فعال: ${report.aliveCount}")
                    appendLine("• کانفیگ‌های سوختهٔ حذف‌شده: ${report.deadRemovedCount}")
                    appendLine("• سریع‌ترین پینگ ثبت‌شده: ${if (report.fastestLatencyMs > 0) "${report.fastestLatencyMs} میلی‌ثانیه" else "آماده"}")
                    appendLine()
                    appendLine("📋 ۵ کانفیگ برتر آماده اتصال:")
                    report.sortedAliveLinks.take(5).forEachIndexed { idx, uri ->
                        val remark = uri.substringAfter('#', "Server-${idx + 1}").let {
                            runCatching { java.net.URLDecoder.decode(it, "UTF-8") }.getOrDefault(it)
                        }
                        appendLine("${idx + 1}. $remark")
                    }
                }
            } else {
                buildString {
                    appendLine("✅ Subscription Cleaned & Sorted by Ping!")
                    appendLine()
                    appendLine("• Total Checked: ${report.totalChecked}")
                    appendLine("• Alive & Ready: ${report.aliveCount}")
                    appendLine("• Dead Removed: ${report.deadRemovedCount}")
                    appendLine("• Fastest Ping: ${report.fastestLatencyMs} ms")
                }
            }

            MaterialAlertDialogBuilder(this@MainActivity)
                .setTitle(
                    if (isFarsi) "🧹 نتیجهٔ پالایش و مرتب‌سازی کانفیگ‌ها"
                    else "🧹 Dead-Config Cleaner & Ping Sorter Result",
                )
                .setMessage(summary)
                .setNegativeButton(android.R.string.cancel, null)
                .setPositiveButton(
                    if (isFarsi) "🚀 ذخیرهٔ کانفیگ‌های سالم و اتصال فوری"
                    else "🚀 Save Sorted Configs & Connect Now",
                ) { _, _ ->
                    activityScope.launch {
                        val superTitle = if (isFarsi) "💎 سوپر-اشتراک ترکیبی (سریع‌ترین‌های همهٔ اشتراک‌ها)" else "💎 Super-Merged Subscription (Fastest)"
                        val subTitle = if (mergeIntoSuperSubscription) {
                            superTitle
                        } else {
                            activeSub?.name ?: if (isFarsi) "⚡ کانفیگ‌های پالایش‌شده (بر اساس پینگ)" else "⚡ Cleaned & Sorted Configs"
                        }
                        val targetExisting = if (mergeIntoSuperSubscription) {
                            subs.firstOrNull { it.name == superTitle }
                        } else {
                            activeSub
                        }
                        val rawJoined = report.sortedAliveLinks.joinToString("\n")
                        val saved = withContext(Dispatchers.IO) {
                            if (targetExisting != null) {
                                userSubscriptionManager.update(targetExisting.id, subTitle, rawJoined)
                            } else {
                                userSubscriptionManager.add(subTitle, rawJoined)
                            }
                        }
                        userSubscriptionManager.select(saved.id)
                        val curAether = aetherPreferenceStore.read()
                        if (curAether.enabled) aetherPreferenceStore.save(curAether.copy(enabled = false))
                        orbotEnginePreferenceStore.setEnabled(false)
                        renderSubscriptions()
                        onSubscriptionSelected()
                        renderAdvancedControls()
                        openScreen(SCREEN_HOME)
                        if (currentVpnServiceState == VpnState.Started) {
                            reconnectForConnectionOptionChange()
                        } else {
                            beginConnectFlow(Actions.CONNECT)
                        }
                    }
                }
                .create()
                .showCatClientDialog()
        }
    }

    /**
     * Full conversational guide dialog explaining every section and button in simple, everyday language.
     */
    private fun showPlainLanguageFullGuideDialog() {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val guideText = if (isFarsi) {
            """
            👋 سلام! اگر با اصطلاحات فنی (مثل SNI، فرگمنت، وارپ، ساکس یا DNS) آشنا نیستی، اصلاً نگران نباش. اینجا به زبان خیلی ساده بهت می‌گیم هر دکمه دقیقاً چکار می‌کنه:

            ────────────────────────
            🦊 ۱) کارت «فایرفاکس VPN (FENIX — ۵۰ گیگ رایگان)»
            • این چیه؟ مرورگر معروف فایرفاکس یک VPN داخلی روی سرورهای شرکت Fastly داره که برخلاف کلادفلر تو ایران فیلتر نیست و به هر ایمیل رایگان ماهی ۵۰ گیگ حجم مجانی میده!
            • «🦊 اتصال فوری با فایرفاکس VPN» رو بزنی چی میشه؟
              👈 سریع‌ترین سرور فایرفاکس رو انتخاب می‌کنه، قفل فیلترینگ رو می‌شکنه و کل اینترنت گوشیت رو وصل می‌کنه.
            • «👤 افزودن حساب ۵۰ گیگ» رو بزنی چی میشه؟
              👈 می‌تونی ایمیل و رمز حساب فایرفاکست رو بزنی (حتی می‌تونی ۲ یا ۳ تا اکانت رایگان اضافه کنی تا بشه ۱۵۰ گیگ در ماه و وقتی یکی تموم شد خودش بره رو بعدی!).

            ────────────────────────
            🪄 ۲) دکمه «تعمیر خودکار کانفیگ من و اتصال فوری»
            • کی بزنم؟ وقتی خودت کانفیگ یا اشتراک خریدی (یا ساختی)، ولی روی همراه اول یا ایرانسل وصل نمیشه یا سرعتش صفره.
            • اینو بزنی چی میشه؟
              👈 برنامه خودش می‌گرده کانفیگ واقعی تو رو پیدا می‌کنه (نه کانفیگ فرضی!)، آی‌پی‌های باز رو تست می‌کنه، بستهٔ اول اینترنت رو تکهتکه (برش SNI) می‌کنه تا فایروال مخابرات نفهمه کجا داری میری، و بلافاصله وصلت می‌کنه!

            ────────────────────────
            🚀 ۳) دکمه «اتصال مستقیم Aether» و «⚡ ساخت ۱-کلیکی آموزش PattNG (MASQUE in MASQUE + HTTP/2 + Psiphon)»
            • کی بزنم؟ وقتی هیچ کانفیگ و اکانتی نداری و می‌خوای با روش جدید PattNG (دو لایه MASQUE تو در تو روی HTTP/2 + خروج از سایفون آلمان/هلند/آمریکا) وصل بشی که روی شدیدترین فایروال‌های همراه اول و ایرانسل کار می‌کنه.
            • «⚡ ساخت ۱-کلیکی آموزش PattNG» رو بزنی چی میشه؟
              👈 تمام مراحل آموزش PattNG رو خودش اتوماتیک برات انجام میده: ۱) دو جفت کلید جدید WARP می‌گیره (و ۳ تا کلید زاپاس هم توی استخر ذخیره می‌کنه)، ۲) پروتکل رو روی MASQUE in MASQUE و ترنسپورت رو روی HTTP/2 می‌ذاره، ۳) خروجی رو روی WARP > Psiphon (یا زنجیره معکوس Psiphon > WARP برای نداشتن کپچای گوگل) می‌ذاره، ۴) هر دو اندپوینت Outer و Inner رو اسکن می‌کنه و ۵) کانفیگ رو تو لیست اصلی ذخیره و وصل می‌کنه!
            • «🌍 دکمه‌های پرچم آلمان/هلند/آمریکا/فنلاند/انگلیس» رو بزنی چی میشه؟
              👈 بدون نیاز به اسکن دوباره یا گرفتن کلید جدید، در جا کشور سایفونت رو عوض می‌کنه!

            ────────────────────────
            ✨ ۴) دکمه «تست باز بودن Gemini، ChatGPT و یوتیوب»
            • کی بزنم؟ وقتی VPN وصله ولی جمینی میگه «کشور شما پشتیبانی نمی‌شود» یا یوتیوب بالا نمیاد.
            • اینو بزنی چی میشه؟
              👈 هر ۴ سرویس هوش مصنوعی و یوتیوب رو تست می‌کنه و با یک کلیک آی‌پی آمریکا (US) رو برات فعال می‌کنه تا تحریم دور زده بشه.

            ────────────────────────
            🧪 ۵) دکمه «آزمایشگاه نت ملی و سایت‌های سفید»
            • کی بزنم؟ وقتی اینترنت خیلی خراب یا «نت ملی» شده و کلادفلر کامل بسته شده.
            • داخلش چی داره؟
              ۱. اسکنر سایت‌ها و شرکت‌های باز غیرکلادفلر (مثل Fastly، Akamai، گوگل و آروان) که کانفیگ واقعی خودت رو روی آی‌پی باز اون‌ها سوار می‌کنه و وصل می‌کنه.
              ۲. پروکسی محلی برش SNI که نام سایت‌های مجاز بانکی/داخلی رو جلوی دید فایروال می‌ذاره و ترافیک اصلیت رو رد می‌کنه.
              ۳. ۵ روش اسپوف کلادفلر (مخصوص دور زدن قفل همراه اول و ایرانسل روی کانفیگ خودت).

            ────────────────────────
            📡 ۶) دکمه «متدهای DNS و ریزولور (WhiteDNS)»
            • کی بزنم؟ وقتی همهٔ پورت‌ها بسته شده و فقط پورت DNS کار می‌کنه.
            • «🚀 اتصال مستقیم تانل DNS» رو بزنی چی میشه؟
              👈 ۵۲ سرور DNS ایران و جهان رو بررسی می‌کنه و ترافیک رو از داخل بسته‌های DNS رد می‌کنه.

            ────────────────────────
            🧦 ۷) دکمه «بخش اختصاصی ساکس۵ (SOCKS5)»
            • اینو بزنی چی میشه؟
              👈 از ۷ منبع زنده دنیا پروکسی‌های سالم رو می‌گیره، پینگ می‌گیره و هم برای تلگرام و هم برای کل گوشی وصلشون می‌کنه.

            ────────────────────────
            🚀 ۸) دکمه «مرکز ۴ قابلیت طلایی (ضد-فریز · تفکیک بانک/تلگرام · گیمینگ · هات‌اسپات QR و تعویض آی‌پی)»
            • ۱) «⚡ تعویض فوری آی‌پی/لبهٔ تمیز» و «🔄 پایشگر خودکار ضد-فریز» رو بزنی چی میشه؟
              👈 بدون اینکه VPN قطع بشه، در زیر ۱ ثانیه آی‌پی کلودفلر رو عوض می‌کنه! و اگر روشنش بذاری، هر وقت مخابرات بعد از چند دقیقه اینترنت رو فریز کرد، خودش اتوماتیک تو پس‌زمینه آی‌پی رو عوض می‌کنه تا تلگرام و یوتیوبت قطع نشه!
            • ۲) «🏦 عبور مستقیم بانک‌ها، اسنپ، تپسی» یا «🎯 فقط تلگرام، اینستاگرام و یوتیوب روی VPN» رو بزنی چی میشه؟
              👈 با یک کلیک همراه بانک‌ها و اسنپ رو از فیلترشکن جدا می‌کنه تا دیگه هیچ‌وقت خطای «فیلترشکن را خاموش کنید» ندن، یا فقط تلگرام/اینستاگرام/یوتیوب رو روی VPN می‌ذاره تا حجمت نسوزه!
            • ۳) «🎮 بوستر گیمینگ و تماس ضد-پکت‌لاس» رو بزنی چی میشه؟
              👈 اولویت بسته‌های صدا و بازی رو بالا می‌بره و نمی‌ذاره آنتن 4G/5G سیم‌کارت به خواب بره تا وسط کالاف/پابجی یا تماس واتس‌اپ پینگت نپره!
            • ۴) «📲 اشتراک‌گذاری با QR Code» و «🧹 حذف کانفیگ‌های سوخته» رو بزنی چی میشه؟
              👈 یک بارکد و آی‌پی بهت میده که آیفون، لپ‌تاپ، تلویزیون یا PS5 رو بدون نصب هیچ برنامه‌ای به اینترنت بدون فیلتر گوشیت وصل کنی، و با یک کلیک همهٔ کانفیگ‌های خراب رو پاک و سالم‌ها رو به ترتیب پینگ مرتب می‌کنه!

            ────────────────────────
            🧰 ۹) دکمه «۱۸) جعبه‌ابزار» (در مرکز ۲۰۲۶ و در منوی «＋ افزودن سرور»)
            • «📂 وارد کردن از فایل» رو بزنی چی میشه؟
              👈 فایل ‎.conf‎ وایرگارد، فایل Clash/YAML، sing-box/JSON یا یک فایل متنی پر از لینک رو از حافظهٔ گوشی انتخاب می‌کنی و مستقیم اشتراک میشه. از تلگرام هم می‌تونی روی لینک یا فایل «اشتراک‌گذاری» بزنی و Cat Client رو انتخاب کنی.
            • «💾 پشتیبان» و «♻️ بازگردانی» رو بزنی چی میشه؟
              👈 همهٔ اشتراک‌هات تو یک فایل ذخیره میشه؛ گوشی رو عوض کردی، همون فایل رو بازگردانی کن.
            • «🔒 قفل برنامه» رو بزنی چی میشه؟
              👈 یک رمز عددی (و اثر انگشت/رمز گوشی) می‌ذاری که هر کی گوشیت دستش بود نتونه کانفیگ‌هات رو ببینه.
            • «⏰ رفرش خودکار» چیه؟
              👈 هر ۶ ساعت اشتراک‌هات رو آپدیت می‌کنه و اگه حجمت داره تموم میشه یا ۳ روز به انقضا مونده، نوتیفیکیشن میده.
            • اسکنرهای WhiteDNS (ASN، SNI، پروکسی HTTP/SOCKS5، سرعت و پکت‌لاس، ریزالور DNS، کانفیگ‌ساز):
              👈 مثلاً «کانفیگ‌ساز» رو بزنی: کانفیگ خودت رو می‌دی + آی‌پی‌های تمیزی که اسکنر پیدا کرده، و برات همون کانفیگ رو با آی‌پی‌های تمیز (با همان پورت) می‌سازه.
            • «🩺 وضعیت موتورها» چیه؟
              👈 صادقانه میگه کدوم نوع کانفیگ واقعاً روی گوشیت کار می‌کنه: تانل DNS فقط با لینک واقعی slipnet:// (موتور SlipNet)، فایرفاکس فقط با حساب، paqet فقط با سرور واسط؛ دیگه هیچ‌کدوم بی‌صدا «مستقیم» وصل نمیشن.
            """.trimIndent()
        } else {
            """
            👋 Welcome! You don't need any technical knowledge to use these tools. Here is what each button does in plain language:

            1) 🦊 Firefox VPN (FENIX — 50 GB/mo Free):
               Uses Mozilla's official Fastly edge servers (which aren't blocked like Cloudflare) to connect your whole phone. You can add multiple free Firefox accounts (50 GB each) with automatic failover.

            2) 🪄 1-Click Repair My Config & Connect:
               Automatically takes your existing subscription/config, wraps it in our local Anti-DPI SNI Splitter + 5 Cloudflare Spoof methods, and connects immediately.

            3) 🚀 Connect Aether Now / 🤖 Auto-Scan & Build:
               Free serverless Cloudflare WARP/MASQUE + 29-country Psiphon chain. Asks whether you want an Iran IP or Foreign Country IP, scans your ISP, and connects.

            4) 🧪 Net Melli Whitelist Lab:
               For severe blackouts when Cloudflare is blocked: scans open Non-Cloudflare CDNs (Akamai, Fastly, Google, Arvan) and repairs your real configs to connect through them.

            5) 📡 DNS & Resolver Methods:
               Scans 52 DNS resolvers and connects via 9 DNS tunnel engines when standard ports are blocked.

            6) 🧰 18) Toolbox (2026 hub and the "+ Add server" sheet):
               Import a WireGuard .conf / Clash YAML / sing-box JSON / text file, back up and restore all subscriptions, lock the app with a PIN or fingerprint, auto-refresh subscriptions every 6 h with expiry / data-cap alerts, the WhiteDNS scanners (ASN export, SNI, HTTP/SOCKS5 proxy, speed & loss, DNS resolver, Config Maker) and an honest engine-status page that says which config types really work on this phone.
            """.trimIndent()
        }

        val tv = TextView(this).apply {
            text = guideText
            textSize = 12.5f
            typeface = CatClientBodyTypeface
            setTextColor(TEXT_PRIMARY)
            setLineSpacing(dp(2).toFloat(), 1.15f)
            setPadding(dp(18), dp(14), dp(18), dp(14))
        }
        val scroll = ScrollView(this).apply { addView(tv) }
        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "📖 راهنمای کامل به زبان ساده (اینو بزنی این میشه!)"
                else "📖 Complete Plain-Language Guide",
            )
            .setView(scroll)
            .setNegativeButton(android.R.string.ok, null)
            .setNeutralButton(if (isFarsi) "🪄 تعمیر کانفیگ من و اتصال" else "🪄 Repair My Config") { _, _ ->
                runOneClickRepairMyRealConfigAndConnect()
            }
            .setPositiveButton(if (isFarsi) "🦊 اتصال فوری فایرفاکس VPN" else "🦊 Connect Firefox VPN") { _, _ ->
                connectFirefoxVpnDirectly()
            }
            .create()
            .showCatClientDialog()
    }

    /**
     * Dedicated card for **Firefox Browser VPN (`FENIX` / Mozilla IP Protection on Fastly)**
     * offering 50 GB/month per free Firefox Account, multi-account auto-failover, and 35 countries.
     */
    private fun buildFirefoxVpnFenixCard(): View {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val card = advancedSettingsPanel()

        card.addView(
            TextView(this).apply {
                text = if (isFarsi) {
                    "🦊 فایرفاکس VPN (FENIX · مشابه MLM VPN — ۵۰ گیگ رایگان در ماه)"
                } else {
                    "🦊 Firefox Browser VPN (FENIX · 50 GB/mo Free on Fastly)"
                }
                textSize = 15.5f
                typeface = CatClientBodyBoldTypeface
                setTextColor(TEAL)
                layoutDirection = View.LAYOUT_DIRECTION_LOCALE
            },
            LinearLayout.LayoutParams(-1, -2),
        )
        card.addView(
            TextView(this).apply {
                text = if (isFarsi) {
                    "ترافیک کل گوشی روی سرورهای Fastly مرورگر فایرفاکس (غیرکلادفلر و باز در ایران) در ۳۵ کشور دنیا + پشتیبانی از چند اکانت همزمان با چرخش خودکار ۵۰ گیگابایت و برش بسته TLS ضد فیلترینگ."
                } else {
                    "Full-device VPN over Mozilla's Fastly Edge in 35 countries — 50 GB/month per free Firefox account with multi-account auto-failover and Anti-DPI TLS splitting."
                }
                textSize = 12f
                setTextColor(TEXT_SECONDARY)
                setLineSpacing(dp(2).toFloat(), 1f)
                layoutDirection = View.LAYOUT_DIRECTION_LOCALE
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(4) },
        )

        val statusView = TextView(this).apply {
            textSize = 12f
            typeface = CatClientDataTypeface
            setTextColor(TEXT_PRIMARY)
            setLineSpacing(dp(2).toFloat(), 1.05f)
            layoutDirection = View.LAYOUT_DIRECTION_LOCALE
        }
        card.addView(statusView, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) })

        fun refreshFenixSummary() {
            val accounts = FirefoxVpnEngine.loadAccounts(this)
            val activeAcc = FirefoxVpnEngine.selectBestActiveAccount(accounts)
            val selCode = FirefoxVpnEngine.readSelectedCountryCode(this)
            val countries = FirefoxVpnEngine.getAvailableCountries(this)
            val countryLabel = when (selCode) {
                FirefoxVpnEngine.COUNTRY_FASTEST ->
                    if (isFarsi) "⚡ سریع‌ترین کشور (انتخاب خودکار با کمترین پینگ)" else "⚡ Fastest Country (Auto-Ping)"
                else -> {
                    val c = countries.firstOrNull { it.code.equals(selCode, ignoreCase = true) } ?: countries.first()
                    "${c.flag} ${if (isFarsi) c.nameFa else c.nameEn}"
                }
            }
            val cleanIp = FirefoxVpnEngine.readCleanFastlyEdgeIp(this)
                .ifBlank { if (isFarsi) "خودکار (سرور مستقیم Fastly)" else "Auto (Direct Fastly Edge)" }
            val fragOn = FirefoxVpnEngine.isTlsFragmentEnabled(this)

            statusView.text = if (isFarsi) {
                buildString {
                    if (activeAcc != null) {
                        append("👤 حساب فعال: ${activeAcc.email} (از ${accounts.size} حساب · چرخش خودکار ۹۵٪)\n")
                        append("📊 حجم رایگان: ${FirefoxVpnEngine.formatQuotaSummaryFa(activeAcc)}\n")
                    } else {
                        append("👤 حساب فایرفاکس: هنوز وارد نشده‌اید (روی «👤 حساب ۵۰ گیگ» یا «🦊 اتصال فوری» بزنید تا با ایمیل یا گوگل ۵۰ گیگ رایگان بگیرید)\n")
                    }
                    append("🌍 کشور خروجی: $countryLabel\n")
                    append("🛡️ ضد فیلترینگ: ${if (fragOn) "برش TLS SNI روشن ✅" else "عادی"} · لبه Fastly: $cleanIp")
                }
            } else {
                buildString {
                    if (activeAcc != null) {
                        append("👤 Active Account: ${activeAcc.email} (${accounts.size} total · 95% auto-failover)\n")
                        append("📊 Free Quota: ${FirefoxVpnEngine.formatQuotaSummaryEn(activeAcc)}\n")
                    } else {
                        append("👤 Account: Not signed in yet (Tap '👤 50GB Accounts' or '🦊 Connect' to sign in via Mozilla/Google for 50 GB/mo free)\n")
                    }
                    append("🌍 Exit Country: $countryLabel\n")
                    append("🛡️ Anti-DPI: ${if (fragOn) "TLS SNI Split ON ✅" else "Standard"} · Fastly Edge: $cleanIp")
                }
            }
        }
        refreshFenixSummary()

        fun fenixBtn(label: String, accent: Boolean = false, onClick: () -> Unit): MaterialButton =
            MaterialButton(this).apply {
                text = label
                isAllCaps = false
                textSize = 12f
                typeface = CatClientBodyBoldTypeface
                minHeight = dp(44)
                minimumHeight = dp(44)
                insetTop = 0
                insetBottom = 0
                cornerRadius = dp(12)
                setPadding(dp(10), 0, dp(10), 0)
                if (accent) {
                    backgroundTintList = ColorStateList.valueOf(TEAL)
                    setTextColor(BACKGROUND)
                } else {
                    backgroundTintList = ColorStateList.valueOf(withAlpha(SURFACE, 215))
                    strokeWidth = dp(1)
                    strokeColor = ColorStateList.valueOf(withAlpha(OUTLINE, 200))
                    setTextColor(TEXT_PRIMARY)
                }
                setOnClickListener { onClick() }
            }

        // Primary 1-Click Connect Button
        card.addView(
            fenixBtn(
                label = if (isFarsi) "🦊 اتصال فوری با فایرفاکس VPN (روشن کردن کل گوشی)" else "🦊 Connect Firefox VPN Now (Full Device)",
                accent = true,
            ) {
                connectFirefoxVpnDirectly { refreshFenixSummary() }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(10) },
        )

        // Row: Country Picker (35 Countries) + Account Manager (50 GB/mo)
        val row1 = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutDirection = View.LAYOUT_DIRECTION_LOCALE
            addView(
                fenixBtn(if (isFarsi) "🌍 کشور (۳۵ کشور) ▾" else "🌍 Country (35) ▾") {
                    showFirefoxCountryPickerDialog { refreshFenixSummary() }
                },
                LinearLayout.LayoutParams(0, -2, 1f),
            )
            addView(
                fenixBtn(if (isFarsi) "👤 حساب ۵۰ گیگ ▾" else "👤 50GB Accounts ▾") {
                    showFirefoxAccountManagerDialog { refreshFenixSummary() }
                },
                LinearLayout.LayoutParams(0, -2, 1f).apply { marginStart = dp(8) },
            )
        }
        card.addView(row1, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) })

        // Secondary Row: Full FENIX Hub & Ping Scanner
        card.addView(
            fenixBtn(
                label = if (isFarsi) "⚙️ پنل کامل فایرفاکس VPN، تست پینگ ۳۵ کشور و اسکن Fastly" else "⚙️ Full Firefox VPN Hub, 35-Country Ping & Fastly Scan",
                accent = false,
            ) {
                showFirefoxVpnFenixHubDialog { refreshFenixSummary() }
            },
            LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) },
        )

        return card
    }

    private fun showFirefoxCountryPickerDialog(onChanged: () -> Unit = {}) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val countries = FirefoxVpnEngine.getAvailableCountries(this)
        val codes = listOf(FirefoxVpnEngine.COUNTRY_FASTEST) + countries.map { it.code }
        val labels = buildList {
            add(
                if (isFarsi) "⚡ سریع‌ترین کشور خودکار (تست پینگ لحظه‌ای هنگام اتصال)"
                else "⚡ Fastest Country Automatically (Live Ping on Connect)",
            )
            countries.forEach { c ->
                val name = if (isFarsi) c.nameFa else c.nameEn
                add("${c.flag} $name (${c.code}) · ${c.exactEndpoint}")
            }
        }.toTypedArray()
        val currentCode = FirefoxVpnEngine.readSelectedCountryCode(this)
        val checkedIdx = codes.indexOfFirst { it.equals(currentCode, ignoreCase = true) }.coerceAtLeast(0)

        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "🌍 انتخاب کشور خروجی فایرفاکس VPN (۳۵ کشور روی شبکه Fastly)"
                else "🌍 Select Firefox VPN Country (35 Fastly Locations)",
            )
            .setSingleChoiceItems(labels, checkedIdx) { dlg, idx ->
                dlg.dismiss()
                val chosenCode = codes[idx]
                FirefoxVpnEngine.saveSelectedCountryCode(this, chosenCode)
                onChanged()
                Toast.makeText(
                    this,
                    if (isFarsi) "✅ کشور فایرفاکس VPN روی «${labels[idx].substringBefore(" ·")}» تنظیم شد"
                    else "✅ Firefox VPN country set to '${labels[idx].substringBefore(" ·")}'",
                    Toast.LENGTH_SHORT,
                ).show()
            }
            .setNeutralButton(if (isFarsi) "🔄 دریافت آخرین لیست سرورهای موزیلا" else "🔄 Sync Mozilla Servers") { _, _ ->
                activityScope.launch {
                    val synced = withContext(Dispatchers.IO) {
                        FirefoxVpnEngine.syncRemoteSettingsCountries(this@MainActivity)
                    }
                    onChanged()
                    Toast.makeText(
                        this@MainActivity,
                        if (isFarsi) "✅ لیست ${synced.size} کشور از سرور موزیلا بروزرسانی شد"
                        else "✅ Synced ${synced.size} countries from Mozilla Remote Settings",
                        Toast.LENGTH_SHORT,
                    ).show()
                }
            }
            .setNegativeButton(android.R.string.cancel, null)
            .create()
            .showCatClientDialog()
    }

    private fun showFirefoxAccountManagerDialog(onChanged: () -> Unit = {}) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val accounts = FirefoxVpnEngine.loadAccounts(this)
        val accountLines = if (accounts.isEmpty()) {
            if (isFarsi) "هنوز حسابی اضافه نشده است (هر حساب رایگان فایرفاکس = ۵۰ گیگابایت در ماه)."
            else "No Firefox account added yet (each free account gives 50 GB/month)."
        } else {
            accounts.mapIndexed { idx, acc ->
                val quota = if (isFarsi) FirefoxVpnEngine.formatQuotaSummaryFa(acc) else FirefoxVpnEngine.formatQuotaSummaryEn(acc)
                val status = if (acc.hasUnexpiredProxyPass()) "🟢" else "🟡"
                "${idx + 1}. $status ${acc.email}\n   📊 $quota"
            }.joinToString("\n\n")
        }

        val options = if (isFarsi) {
            arrayOf(
                "🌐 ۱) ورود آسان با صفحه رسمی موزیلا / گوگل داخل برنامه (پیشنهادی ⭐ · مشابه MLM VPN)",
                "📧 ۲) ورود مستقیم با ایمیل و رمز عبور فایرفاکس (با حل خودکار چالش Fastly + کد ۲ مرحله‌ای)",
                "🔑 ۳) افزودن سریع با توکن / SessionToken / JSON (از مرورگر، foxyvpn یا MLM VPN)",
                "🔄 ۴) بروزرسانی حجم ۵۰ گیگابایت و تمدید توکن همه حساب‌ها",
                "🗑️ ۵) حذف یکی از حساب‌های ذخیره‌شده",
            )
        } else {
            arrayOf(
                "🌐 1) Easy Sign-In via In-App Mozilla Page / Google (Recommended ⭐ · Like MLM VPN)",
                "📧 2) Direct Sign-In with Firefox Email & Password (Fastly Auto-Solver + 2FA)",
                "🔑 3) Quick Import via Token / SessionToken / JSON (from Firefox, foxyvpn, or MLM VPN)",
                "🔄 4) Refresh 50 GB Quota & Renew ProxyPass for All Accounts",
                "🗑️ 5) Remove a Saved Account",
            )
        }

        val headerView = TextView(this).apply {
            text = accountLines
            textSize = 12f
            typeface = CatClientDataTypeface
            setTextColor(TEXT_PRIMARY)
            setPadding(dp(20), dp(10), dp(20), dp(4))
        }

        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "👤 مدیریت حساب‌های ۵۰ گیگ فایرفاکس (پشتیبانی از چند اکانت)"
                else "👤 Firefox VPN 50 GB Accounts (Multi-Account Pool)",
            )
            .setCustomTitle(
                LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(20), dp(16), dp(20), dp(4))
                    addView(
                        TextView(this@MainActivity).apply {
                            text = if (isFarsi) "👤 حساب‌های ۵۰ گیگ فایرفاکس VPN" else "👤 Firefox VPN 50 GB Accounts"
                            textSize = 16f
                            typeface = CatClientBodyBoldTypeface
                            setTextColor(TEAL)
                        },
                    )
                    addView(headerView)
                },
            )
            .setItems(options) { _, which ->
                when (which) {
                    0 -> showFirefoxWebViewLoginDialog(onChanged)
                    1 -> showFirefoxEmailLoginDialog(onChanged)
                    2 -> showFirefoxTokenImportDialog(onChanged)
                    3 -> {
                        if (accounts.isEmpty()) {
                            Toast.makeText(
                                this,
                                if (isFarsi) "ابتدا یک حساب فایرفاکس اضافه کنید" else "Add a Firefox account first",
                                Toast.LENGTH_SHORT,
                            ).show()
                        } else {
                            Toast.makeText(
                                this,
                                if (isFarsi) "⏳ در حال بروزرسانی توکن و سهمیه ۵۰ گیگ حساب‌ها…" else "⏳ Refreshing accounts & 50 GB quota…",
                                Toast.LENGTH_SHORT,
                            ).show()
                            activityScope.launch {
                                withContext(Dispatchers.IO) {
                                    accounts.forEach { acc ->
                                        runCatching { FirefoxVpnEngine.refreshAndActivateAccountPass(this@MainActivity, acc) }
                                    }
                                }
                                onChanged()
                                Toast.makeText(
                                    this@MainActivity,
                                    if (isFarsi) "✅ توکن و سهمیه ۵۰ گیگ حساب‌ها بروزرسانی شد" else "✅ Refreshed accounts & quota",
                                    Toast.LENGTH_LONG,
                                ).show()
                            }
                        }
                    }
                    4 -> {
                        if (accounts.isEmpty()) return@setItems
                        val titles = accounts.map { it.email }.toTypedArray()
                        MaterialAlertDialogBuilder(this)
                            .setTitle(if (isFarsi) "حذف حساب فایرفاکس" else "Remove Firefox Account")
                            .setItems(titles) { _, rIdx ->
                                FirefoxVpnEngine.removeAccount(this, accounts[rIdx].id)
                                onChanged()
                                Toast.makeText(
                                    this,
                                    if (isFarsi) "🗑️ حساب حذف شد" else "🗑️ Account removed",
                                    Toast.LENGTH_SHORT,
                                ).show()
                            }
                            .setNegativeButton(android.R.string.cancel, null)
                            .create()
                            .showCatClientDialog()
                    }
                }
            }
            .setNegativeButton(android.R.string.cancel, null)
            .create()
            .showCatClientDialog()
    }

    /**
     * In-App Official Mozilla WebView Sign-In (`https://accounts.firefox.com/`):
     * Supports Email/Password, "Continue with Google" (Gmail), Apple Sign-In, new account sign-up,
     * and Fastly CAPTCHA challenges, then automatically extracts `sessionToken` from
     * `window.localStorage.getItem("__fxa_storage.accounts")` and activates 50 GB/month!
     */
    @Suppress("SetJavaScriptEnabled")
    private fun showFirefoxWebViewLoginDialog(onChanged: () -> Unit = {}) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        var completed = false
        var dialogRef: AlertDialog? = null

        var lastTypedEmail = ""
        val statusBanner = TextView(this).apply {
            text = if (isFarsi) {
                "💡 برای جیمیل (@gmail.com): ایمیل خود را در کادر بالای صفحهٔ موزیلا بنویسید و دکمهٔ آبی را بزنید (روی Continue with Google نزنید تا گوگل خطا ندهد!)."
            } else {
                "💡 Using Gmail? Enter your @gmail.com address in Mozilla's top email box and tap the blue button (avoid 'Continue with Google' to bypass Google's WebView block)."
            }
            textSize = 11.5f
            typeface = CatClientBodyBoldTypeface
            setTextColor(TEAL)
            setPadding(dp(12), dp(8), dp(12), dp(8))
        }

        val webView = object : android.webkit.WebView(this) {
            // Crucial for AlertDialog: tells AlertController.canTextInput() that this dialog
            // contains a text editor so it does NOT set FLAG_ALT_FOCUSABLE_IM (which blocks the keyboard).
            override fun onCheckIsTextEditor(): Boolean = true
        }.apply {
            layoutParams = LinearLayout.LayoutParams(-1, dp(430))
            isFocusable = true
            isFocusableInTouchMode = true
            settings.javaScriptEnabled = true
            settings.domStorageEnabled = true
            settings.databaseEnabled = true
            settings.javaScriptCanOpenWindowsAutomatically = true
            settings.loadsImagesAutomatically = true
            // Use the device's genuine Chromium UA stripped of '; wv' and 'Version/4.0' so
            // navigator.userAgent matches the Blink engine & Sec-CH-UA headers (preventing mismatch blocks).
            val rawUa = runCatching { android.webkit.WebSettings.getDefaultUserAgent(this@MainActivity) }
                .getOrDefault("Mozilla/5.0 (Linux; Android 14; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/131.0.0.0 Mobile Safari/537.36")
            settings.userAgentString = rawUa
                .replace("; wv)", ")")
                .replace("; wv;", ";")
                .replace(Regex("""Version/\d+\.\d+\s*"""), "")
            setOnTouchListener { v, event ->
                if (event.action == android.view.MotionEvent.ACTION_DOWN ||
                    event.action == android.view.MotionEvent.ACTION_UP
                ) {
                    dialogRef?.window?.clearFlags(
                        android.view.WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                            android.view.WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM,
                    )
                    if (!v.hasFocus()) {
                        v.requestFocus()
                    }
                }
                false
            }
        }
        runCatching {
            val cm = android.webkit.CookieManager.getInstance()
            cm.setAcceptCookie(true)
            cm.setAcceptThirdPartyCookies(webView, true)
        }

        val quickTypeInput = EditText(this).apply {
            hint = if (isFarsi) "ایمیل یا رمز (در صورت نیاز اینجا تایپ/پیست کنید)" else "Type/paste email or password here if needed"
            textSize = 12.5f
            setSingleLine(true)
            layoutDirection = View.LAYOUT_DIRECTION_LTR
            textDirection = View.TEXT_DIRECTION_LTR
            setPadding(dp(10), dp(6), dp(10), dp(6))
        }
        val quickTypeBtn = MaterialButton(
            this,
            null,
            com.google.android.material.R.attr.materialButtonOutlinedStyle,
        ).apply {
            text = if (isFarsi) "⌨️ درج در صفحه" else "⌨️ Fill Field"
            textSize = 11.5f
            isAllCaps = false
            typeface = CatClientBodyBoldTypeface
            setOnClickListener {
                dialogRef?.window?.clearFlags(
                    android.view.WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                        android.view.WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM,
                )
                val typed = quickTypeInput.text?.toString().orEmpty()
                if (typed.isNotEmpty()) {
                    if (typed.contains("@")) lastTypedEmail = typed.trim()
                    val escaped = org.json.JSONObject.quote(typed)
                    webView.evaluateJavascript(
                        """
                        (function(val){
                          try {
                            var el = document.activeElement;
                            if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA')) {
                              var inputs = document.querySelectorAll('input:not([type=hidden]):not([disabled])');
                              for (var i = 0; i < inputs.length; i++) {
                                if (inputs[i].offsetParent !== null) { el = inputs[i]; break; }
                              }
                            }
                            if (el) {
                              el.focus();
                              var setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
                              if (setter && setter.set) { setter.set.call(el, val); } else { el.value = val; }
                              el.dispatchEvent(new Event('input', { bubbles: true }));
                              el.dispatchEvent(new Event('change', { bubbles: true }));
                            }
                          } catch(e) {}
                        })($escaped);
                        """.trimIndent(),
                        null,
                    )
                    quickTypeInput.setText("")
                } else {
                    webView.requestFocus()
                    val imm = getSystemService(Context.INPUT_METHOD_SERVICE) as? android.view.inputmethod.InputMethodManager
                    imm?.showSoftInput(webView, android.view.inputmethod.InputMethodManager.SHOW_FORCED)
                }
            }
        }
        val quickTypeBar = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(10), dp(2), dp(10), dp(6))
            addView(quickTypeInput, LinearLayout.LayoutParams(0, -2, 1f).apply { marginEnd = dp(6) })
            addView(quickTypeBtn, LinearLayout.LayoutParams(-2, -2))
        }

        fun checkWebViewForFxaSession() {
            if (completed || isFinishing || isDestroyed) return
            webView.evaluateJavascript(
                """
                (function(){
                  try {
                    var a = window.localStorage.getItem('__fxa_storage.accounts');
                    if (a && a.indexOf('sessionToken') !== -1) return a;
                    for (var i = 0; i < window.localStorage.length; i++) {
                      var k = window.localStorage.key(i);
                      var v = window.localStorage.getItem(k);
                      if (v && v.indexOf('sessionToken') !== -1) return v;
                    }
                    for (var j = 0; j < window.sessionStorage.length; j++) {
                      var sk = window.sessionStorage.key(j);
                      var sv = window.sessionStorage.getItem(sk);
                      if (sv && sv.indexOf('sessionToken') !== -1) return sv;
                    }
                    return '';
                  } catch(e) { return ''; }
                })();
                """.trimIndent(),
            ) { rawValue ->
                if (completed || rawValue.isNullOrBlank() || rawValue == "null" || rawValue == "\"\"") return@evaluateJavascript
                val pair = FirefoxVpnEngine.extractSessionFromWebViewStorageJson(rawValue) ?: return@evaluateJavascript
                completed = true
                statusBanner.text = if (isFarsi) {
                    "✅ نشست «${pair.second}» دریافت شد! در حال فعال‌سازی سهمیه ۵۰ گیگابایت…"
                } else {
                    "✅ Session for '${pair.second}' captured! Activating 50 GB quota…"
                }
                activityScope.launch {
                    val outcome = withContext(Dispatchers.IO) {
                        FirefoxVpnEngine.loginFromWebViewStorageJson(this@MainActivity, rawValue)
                    }
                    runCatching { dialogRef?.dismiss() }
                    runCatching { webView.destroy() }
                    when (outcome) {
                        is FirefoxVpnEngine.LoginOutcome.Success -> {
                            onChanged()
                            Toast.makeText(
                                this@MainActivity,
                                if (isFarsi) "✅ حساب «${outcome.account.email}» با ۵۰ گیگابایت سهمیه ماهانه فعال شد!"
                                else "✅ Activated '${outcome.account.email}' with 50 GB monthly quota!",
                                Toast.LENGTH_LONG,
                            ).show()
                        }
                        is FirefoxVpnEngine.LoginOutcome.Failure -> {
                            Toast.makeText(
                                this@MainActivity,
                                if (isFarsi) outcome.messageFa else outcome.messageEn,
                                Toast.LENGTH_LONG,
                            ).show()
                        }
                        else -> Unit
                    }
                }
            }
        }

        fun injectFxaDirectEmailGuidance(prefillEmail: String = lastTypedEmail) {
            val escapedPrefill = org.json.JSONObject.quote(prefillEmail)
            val noteText = org.json.JSONObject.quote(
                if (isFarsi) "⚡ جیمیل (@gmail.com) را در همین کادر بالا وارد کنید و دکمهٔ آبی را بزنید (بدون خطای گوگل)"
                else "⚡ Enter your @gmail.com in the top box above and tap the blue button",
            )
            webView.evaluateJavascript(
                """
                (function(prefill, bannerMsg){
                  try {
                    Object.defineProperty(navigator, 'webdriver', { get: function(){ return false; } });
                    // Capture any email typed by the user in any email field
                    var emailInputs = document.querySelectorAll('input[type=email], input[name=email], input[autocomplete=username]');
                    for (var i = 0; i < emailInputs.length; i++) {
                      var inp = emailInputs[i];
                      if (prefill && !inp.value && window.location.hostname.indexOf('firefox.com') !== -1) {
                        var setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
                        if (setter && setter.set) { setter.set.call(inp, prefill); } else { inp.value = prefill; }
                        inp.dispatchEvent(new Event('input', { bubbles: true }));
                        inp.dispatchEvent(new Event('change', { bubbles: true }));
                      }
                      if (!inp.__catHooked) {
                        inp.__catHooked = true;
                        inp.addEventListener('input', function(ev) {
                          try { window.sessionStorage.setItem('__cat_last_email', ev.target.value || ''); } catch(e){}
                        });
                      }
                    }
                    // On Mozilla FxA page, add a clear hint above third-party buttons so users enter Gmail directly in Mozilla's form
                    if (window.location.hostname.indexOf('firefox.com') !== -1 && !document.getElementById('__cat_fxa_hint')) {
                      var firstInput = emailInputs.length > 0 ? emailInputs[0] : null;
                      if (firstInput && firstInput.parentElement) {
                        var hint = document.createElement('div');
                        hint.id = '__cat_fxa_hint';
                        hint.style.cssText = 'background:#0f2922;color:#5eead4;border:1px solid #14b8a6;border-radius:8px;padding:8px 10px;margin:6px 0;font-size:12px;line-height:1.4;text-align:right;direction:rtl;';
                        hint.textContent = bannerMsg;
                        firstInput.parentElement.insertBefore(hint, firstInput);
                      }
                    }
                  } catch(e) {}
                })($escapedPrefill, $noteText);
                """.trimIndent(),
                null,
            )
        }

        webView.webViewClient = object : android.webkit.WebViewClient() {
            override fun onPageStarted(view: android.webkit.WebView?, url: String?, favicon: android.graphics.Bitmap?) {
                super.onPageStarted(view, url, favicon)
                val currentUrl = url.orEmpty()
                // Detect Google's embedded-WebView rejection page (/signin/rejected or disallowed_useragent)
                // and automatically return to Mozilla's direct email sign-in/sign-up flow!
                if (currentUrl.contains("accounts.google.com") &&
                    (currentUrl.contains("/signin/rejected") || currentUrl.contains("disallowed_useragent") || currentUrl.contains("/v3/signin/rejected"))
                ) {
                    statusBanner.setTextColor(0xFFFBBF24.toInt())
                    statusBanner.text = if (isFarsi) {
                        "⚠️ گوگل ورود OAuth داخل برنامه‌ها را محدود کرد! صفحه به فرم مستقیم موزیلا برگشت:\nجیمیل خود را در کادر بالای صفحهٔ موزیلا بنویسید و دکمهٔ آبی را بزنید (کد ۶ رقمی به جیمیلتان ارسال می‌شود)."
                    } else {
                        "⚠️ Google blocked embedded OAuth! Returned to Mozilla's direct email form:\nEnter your Gmail in Mozilla's top box and tap the blue button (a 6-digit code will be sent to your Gmail)."
                    }
                    view?.stopLoading()
                    view?.loadUrl("https://accounts.firefox.com/")
                    return
                }
                injectFxaDirectEmailGuidance()
            }

            override fun onPageFinished(view: android.webkit.WebView?, url: String?) {
                super.onPageFinished(view, url)
                val currentUrl = url.orEmpty()
                if (currentUrl.contains("accounts.google.com") &&
                    (currentUrl.contains("/signin/rejected") || currentUrl.contains("disallowed_useragent"))
                ) {
                    view?.loadUrl("https://accounts.firefox.com/")
                    return
                }
                injectFxaDirectEmailGuidance()
                checkWebViewForFxaSession()
                view?.postDelayed({ checkWebViewForFxaSession() }, 1200L)
                view?.postDelayed({ checkWebViewForFxaSession() }, 2800L)
            }
        }

        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            addView(statusBanner)
            addView(quickTypeBar)
            addView(webView)
        }

        val pollRunnable = object : Runnable {
            override fun run() {
                if (!completed && dialogRef?.isShowing == true) {
                    checkWebViewForFxaSession()
                    mainHandler.postDelayed(this, 1800L)
                }
            }
        }

        dialogRef = MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "🌐 ورود رسمی به حساب فایرفاکس (۵۰ گیگ رایگان)"
                else "🌐 Official Firefox Account Sign-In (50 GB Free)",
            )
            .setView(container)
            .setPositiveButton(if (isFarsi) "✅ وارد شدم (بررسی نشست)" else "✅ I Signed In (Check)") { _, _ ->
                checkWebViewForFxaSession()
            }
            .setNeutralButton(if (isFarsi) "📧 ورود با فرم مستقیم" else "📧 Direct Form") { dlg, _ ->
                completed = true
                dlg.dismiss()
                runCatching { webView.destroy() }
                showFirefoxEmailLoginDialog(onChanged)
            }
            .setNegativeButton(android.R.string.cancel) { _, _ ->
                completed = true
                runCatching { webView.destroy() }
            }
            .create()

        dialogRef.setOnDismissListener {
            completed = true
            mainHandler.removeCallbacks(pollRunnable)
        }
        dialogRef.showCatClientDialog {
            window?.clearFlags(
                android.view.WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                    android.view.WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM,
            )
            window?.setSoftInputMode(
                android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_UNCHANGED or
                    android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE,
            )
        }
        webView.loadUrl("https://accounts.firefox.com/")
        webView.requestFocus()
        mainHandler.postDelayed(pollRunnable, 2000L)
    }

    private fun showFirefoxEmailLoginDialog(onChanged: () -> Unit = {}) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val emailInput = EditText(this).apply {
            hint = if (isFarsi) "ایمیل حساب فایرفاکس (مثلاً user@gmail.com)" else "Firefox Account Email"
            setSingleLine(true)
            layoutDirection = View.LAYOUT_DIRECTION_LTR
            textDirection = View.TEXT_DIRECTION_LTR
        }
        val passInput = EditText(this).apply {
            hint = if (isFarsi) "رمز عبور حساب فایرفاکس" else "Password"
            inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
            setSingleLine(true)
            layoutDirection = View.LAYOUT_DIRECTION_LTR
            textDirection = View.TEXT_DIRECTION_LTR
        }
        val box = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(10), dp(20), dp(4))
            addView(emailInput)
            addView(passInput, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) })
        }

        fun handleLoginOutcome(outcome: FirefoxVpnEngine.LoginOutcome) {
            when (outcome) {
                is FirefoxVpnEngine.LoginOutcome.Success -> {
                    onChanged()
                    Toast.makeText(
                        this@MainActivity,
                        if (isFarsi) "✅ حساب «${outcome.account.email}» با ۵۰ گیگابایت سهمیه ماهانه فعال شد!"
                        else "✅ Activated '${outcome.account.email}' with 50 GB monthly quota!",
                        Toast.LENGTH_LONG,
                    ).show()
                }
                is FirefoxVpnEngine.LoginOutcome.NeedsEmailVerification -> {
                    val isTotp = outcome.verificationMethod.equals("totp-2fa", ignoreCase = true)
                    val codeInput = EditText(this@MainActivity).apply {
                        hint = if (isFarsi) {
                            if (isTotp) "کد ۶ رقمی برنامه Authenticator" else "کد ۶ رقمی ارسال‌شده به ایمیل"
                        } else {
                            if (isTotp) "6-digit Authenticator code" else "6-digit code from email"
                        }
                        setSingleLine(true)
                        layoutDirection = View.LAYOUT_DIRECTION_LTR
                        textDirection = View.TEXT_DIRECTION_LTR
                    }
                    val codeWrap = LinearLayout(this@MainActivity).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(20), dp(10), dp(20), dp(4))
                        addView(codeInput)
                    }
                    MaterialAlertDialogBuilder(this@MainActivity)
                        .setTitle(
                            if (isFarsi) {
                                if (isTotp) "🔐 ورود کد دو مرحله‌ای (Authenticator)" else "📩 ورود کد تایید ایمیل فایرفاکس"
                            } else {
                                if (isTotp) "🔐 Enter Authenticator 2FA Code" else "📩 Enter Email Verification Code"
                            },
                        )
                        .setMessage(
                            if (isFarsi) {
                                if (isTotp) "کد ۶ رقمی برنامه Authenticator حساب ${outcome.email} را وارد کنید:"
                                else "فایرفاکس یک کد تایید ۶ رقمی به ایمیل ${outcome.email} فرستاد. آن را وارد کنید:"
                            } else {
                                if (isTotp) "Enter the 6-digit code from your authenticator app for ${outcome.email}:"
                                else "Enter the verification code sent to ${outcome.email}:"
                            },
                        )
                        .setView(codeWrap)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setPositiveButton(if (isFarsi) "✅ تایید کد و فعال‌سازی" else "✅ Verify & Activate") { _, _ ->
                            val code = codeInput.text?.toString()?.trim().orEmpty()
                            activityScope.launch {
                                val verifiedOutcome = withContext(Dispatchers.IO) {
                                    FirefoxVpnEngine.verifyEmail2faAndCompleteLogin(
                                        this@MainActivity,
                                        outcome.sessionTokenHex,
                                        code,
                                        outcome.email,
                                        outcome.verificationMethod,
                                    )
                                }
                                handleLoginOutcome(verifiedOutcome)
                            }
                        }
                        .create()
                        .showCatClientDialog()
                }
                is FirefoxVpnEngine.LoginOutcome.NeedsUnblockCode -> {
                    val unblockInput = EditText(this@MainActivity).apply {
                        hint = if (isFarsi) "کد ۸ کاراکتری رفع مسدودی (ارسال‌شده به ایمیل)" else "8-character unblock code from email"
                        setSingleLine(true)
                        layoutDirection = View.LAYOUT_DIRECTION_LTR
                        textDirection = View.TEXT_DIRECTION_LTR
                    }
                    val unblockWrap = LinearLayout(this@MainActivity).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(20), dp(10), dp(20), dp(4))
                        addView(unblockInput)
                    }
                    MaterialAlertDialogBuilder(this@MainActivity)
                        .setTitle(if (isFarsi) "🛡️ کد تایید امنیتی موزیلا (Unblock Code)" else "🛡️ Mozilla Security Unblock Code")
                        .setMessage(
                            if (isFarsi) "موزیلا برای اطمینان از ورود شما یک کد ۸ کاراکتری به ایمیل ${outcome.email} ارسال کرد. آن را وارد کنید:"
                            else "Mozilla emailed an 8-character unblock code to ${outcome.email}. Enter it below:",
                        )
                        .setView(unblockWrap)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setPositiveButton(if (isFarsi) "🚀 ادامه ورود" else "🚀 Continue Sign-In") { _, _ ->
                            val unblockCode = unblockInput.text?.toString()?.trim().orEmpty()
                            activityScope.launch {
                                val retryOutcome = withContext(Dispatchers.IO) {
                                    FirefoxVpnEngine.loginWithEmailAndPassword(
                                        this@MainActivity,
                                        outcome.email,
                                        outcome.password,
                                        unblockCode,
                                    )
                                }
                                handleLoginOutcome(retryOutcome)
                            }
                        }
                        .create()
                        .showCatClientDialog()
                }
                is FirefoxVpnEngine.LoginOutcome.Failure -> {
                    MaterialAlertDialogBuilder(this@MainActivity)
                        .setTitle(if (isFarsi) "⚠️ راهنمای ورود به فایرفاکس" else "⚠️ Firefox Sign-In Notice")
                        .setMessage(if (isFarsi) outcome.messageFa else outcome.messageEn)
                        .setPositiveButton(
                            if (isFarsi) "🌐 ورود آسان با صفحه رسمی موزیلا / گوگل" else "🌐 Sign In via Mozilla WebView",
                        ) { _, _ ->
                            showFirefoxWebViewLoginDialog(onChanged)
                        }
                        .setNeutralButton(if (isFarsi) "🔄 تلاش مجدد" else "🔄 Retry") { _, _ ->
                            showFirefoxEmailLoginDialog(onChanged)
                        }
                        .setNegativeButton(android.R.string.cancel, null)
                        .create()
                        .showCatClientDialog()
                }
            }
        }

        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "📧 ورود به حساب فایرفاکس (دریافت ۵۰ گیگ رایگان ماهانه)"
                else "📧 Sign in to Firefox Account (50 GB/mo Free)",
            )
            .setMessage(
                if (isFarsi) "ایمیل و رمز حساب فایرفاکس خود را وارد کنید (یا اگر اکانت شما با جیمیل/گوگل است، روی دکمه «🌐 صفحه وب موزیلا» بزنید):"
                else "Enter your Firefox Account email and password (or tap '🌐 Mozilla Web' for Google Sign-In):",
            )
            .setView(box)
            .setNegativeButton(android.R.string.cancel, null)
            .setNeutralButton(if (isFarsi) "🌐 صفحه وب موزیلا / گوگل" else "🌐 Mozilla Web / Google") { _, _ ->
                showFirefoxWebViewLoginDialog(onChanged)
            }
            .setPositiveButton(if (isFarsi) "🚀 ورود و فعال‌سازی ۵۰ گیگ" else "🚀 Sign In & Activate 50 GB") { _, _ ->
                val email = emailInput.text?.toString()?.trim().orEmpty()
                val pass = passInput.text?.toString().orEmpty()
                Toast.makeText(
                    this,
                    if (isFarsi) "⏳ در حال حل چالش Fastly و ورود به حساب فایرفاکس…" else "⏳ Solving Fastly challenge & signing in…",
                    Toast.LENGTH_SHORT,
                ).show()
                activityScope.launch {
                    val outcome = withContext(Dispatchers.IO) {
                        FirefoxVpnEngine.loginWithEmailAndPassword(this@MainActivity, email, pass)
                    }
                    handleLoginOutcome(outcome)
                }
            }
            .create()
            .showCatClientDialog()
    }

    private fun showFirefoxTokenImportDialog(onChanged: () -> Unit = {}) {
        val isFarsi = appLanguagePreferenceStore.read() == AppLanguage.Persian
        val labelInput = EditText(this).apply {
            hint = if (isFarsi) "نام یا ایمیل دلخواه (مثلاً اکانت ۱)" else "Label or Email (e.g. Account 1)"
            setSingleLine(true)
        }
        val tokenInput = EditText(this).apply {
            hint = if (isFarsi) "توکن Refresh / Access / ProxyPass JWT (eyJ...) یا JSON" else "Refresh/Access Token, ProxyPass JWT (eyJ...) or JSON"
            minLines = 3
            layoutDirection = View.LAYOUT_DIRECTION_LTR
            textDirection = View.TEXT_DIRECTION_LTR
        }
        val box = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(10), dp(20), dp(4))
            addView(labelInput)
            addView(tokenInput, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8) })
        }

        MaterialAlertDialogBuilder(this)
            .setTitle(
                if (isFarsi) "🔑 افزودن سریع حساب با توکن یا JSON"
                else "🔑 Quick Add Account via Token or JSON",
            )
            .setMessage(
                if (isFarsi) "اگر توکن حساب فایرفاکس را از مرورگر فایرفاکس، MLM VPN یا ابزار foxyvpn کپی کرده‌اید، اینجا قرار دهید تا بلافاصله ۵۰ گیگابایت فعال شود:"
                else "Paste your Firefox OAuth token, ProxyPass JWT (eyJ...), or account JSON:",
            )
            .setView(box)
            .setNegativeButton(android.R.string.cancel, null)
            .setPositiveButton(if (isFarsi) "💾 ذخیره و فعال‌سازی" else "💾 Save & Activate") { _, _ ->
                val label = labelInput.text?.toString()?.trim().orEmpty()
                val raw = tokenInput.text?.toString()?.trim().orEmpty()
                if (raw.isEmpty()) {
                    Toast.makeText(
                        this,
                        if (isFarsi) "لطفاً توکن را وارد کنید" else "Please paste the token",
                        Toast.LENGTH_SHORT,
                    ).show()
                    return@setPositiveButton
                }
                activityScope.launch {
                    val added = withContext(Dispatchers.IO) {
                        FirefoxVpnEngine.addAccountFromTokenOrJson(this@MainActivity, label, raw)
                    }
                    if (added != null) {
                        onChanged()
                        Toast.makeText(
                            this@MainActivity,
                            if (isFarsi) "✅ حساب «${added.email}» اضافه شد (${FirefoxVpnEngine.formatQuotaSummaryFa(added)})"
                            else "✅ Added '${added.email}' (${FirefoxVpnEngine.formatQuotaSummaryEn(added)})",
                            Toast.LENGTH_LONG,
                        ).show()
                    }
                }
            }
            .create()
            .showCatClientDialog()
    }

